def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    alive = []
    prev_bids = []
    rich_aggressive = 0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 95 and float(opp.get('budget', 0)) >= 500:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.25
    if no_water >= 2:
        danger += 1.0
    elif no_water >= 1:
        danger += 0.45
    if day >= 8:
        danger += 0.2

    if danger >= 1.4:
        target = max(96.0, max_prev + 4.0, avg_prev + 6.0)
    elif danger >= 0.8:
        target = max(78.0 + 10.0 * scarcity, avg_prev + 2.0)
    else:
        if supply >= 22:
            target = 16.0 + 6.0 * scarcity
        elif supply >= 19:
            target = 24.0 + 10.0 * scarcity
        else:
            target = 38.0 + 16.0 * scarcity

        if max_prev >= 110.0 and hp > 4 and no_water == 0:
            target = min(target, 22.0)
        elif max_prev >= 95.0 and hp > 5 and no_water == 0 and supply >= 19:
            target = min(target, 28.0)
        else:
            target = max(target, min(max_prev * 0.72, 72.0))

    if rich_aggressive >= 2 and danger < 0.8 and supply >= 19:
        target = min(target, 26.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 70.0 * (10 - day) * 0.22
    affordable = max(0.0, budget - reserve_floor)
    if danger >= 1.4:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, max_prev + 3.0, 98.0))
    elif hp <= 4 or no_water >= 1:
        bid = min(budget, max(bid, 82.0, avg_prev + 1.5))

    if budget < 25.0:
        bid = budget

    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Extract yesterday bids from alive opponents
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If opponent(s) were willing to spend very aggressively yesterday, raise slightly.
    # Cindy survived with very high average bid, so treat high prior bid as a signal.
    aggressive_threshold = DAILY_SALARY * 0.95  # 85.5

    # Base bid depends on our urgency (hp/no_water_days)
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    if hp <= 4.0:
        urgency += 2
    if no_water_days >= 2:
        urgency += 2
    if no_water_days >= 3:
        urgency += 3

    # Supply pressure: lower supply means more competition; bid more.
    # Map supply in [15,25] to a factor in [1.25, 0.9]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    supply_factor = 1.25 - 0.35 * t

    if highest_prev_bid >= aggressive_threshold:
        # We expect aggressive contention; bid enough to avoid being starved,
        # but still keep budget for continued competition.
        base = DAILY_SALARY * 0.45
        if urgency >= 4:
            base = DAILY_SALARY * 0.75
        elif urgency >= 2:
            base = DAILY_SALARY * 0.6
        else:
            base = DAILY_SALARY * 0.5

        bid = base * supply_factor
        # Slightly undercut the highest prior bid to avoid waste while still contesting.
        bid = min(bid, highest_prev_bid * 0.92 + 2.0)
    else:
        # No extreme spending observed: bid moderately.
        base = DAILY_SALARY * 0.35
        if urgency >= 4:
            base = DAILY_SALARY * 0.65
        elif urgency >= 2:
            base = DAILY_SALARY * 0.5
        bid = base * supply_factor

    # Budget safety: never bid more than what we can afford while keeping some runway.
    # Reserve fraction increases when urgency is low.
    reserve_frac = 0.25
    if urgency <= 1:
        reserve_frac = 0.45
    elif urgency <= 3:
        reserve_frac = 0.35

    max_affordable = budget * (1.0 - reserve_frac)
    if max_affordable < 0.0:
        max_affordable = 0.0

    bid = max(0.0, min(bid, max_affordable, budget))

    # If we are critically low on HP, push harder.
    if hp <= 1.0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.95))

    return float(bid)

